"""Controller controller -- generated by plugin_authoring. See context.md for this plugin's iteration history."""

from __future__ import annotations

import json
import os
import threading
import udi_interface

LOGGER = udi_interface.LOGGER


class Controller(udi_interface.Node):
    id = 'controller'
    drivers = [{'driver': 'ST', 'value': 0, 'uom': 25, 'name': 'Status'}]
    def __init__(self, polyglot, primary='ctl', address='ctl', name='Nest Thermostat Controller'):
        super().__init__(polyglot, primary, address, name)
        self.poly = polyglot
        self.persist_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "persist")
        os.makedirs(self.persist_dir, exist_ok=True)
        # Synchronization for __start()'s wait-for-configDone gate (see __configDoneHandler).
        self.configDone = threading.Condition()
        self.configDoneAlready = False
        self.poly.setCustomParamsDoc('<![CDATA[<h2>Nest Thermostat setup</h2>\n<p>This plugin uses <b>your own</b> Google Device Access project. Fill in the four fields below. Nothing is ever sent anywhere except to Google.</p>\n\n<h3>The four settings</h3>\n<ul>\n<li><b>project_id</b> - the Project ID of your Device Access project. Find it at <a href="https://console.nest.google.com/device-access/project-list" target="_blank">console.nest.google.com/device-access</a>. It is a long code made of letters, numbers and dashes. This is <i>not</i> the Google Cloud project ID.</li>\n<li><b>client_id</b> - the OAuth Client ID that is linked to that Device Access project. Find it in <a href="https://console.cloud.google.com/apis/credentials" target="_blank">Google Cloud Console - APIs &amp; Services - Credentials</a>. It ends in <code>.apps.googleusercontent.com</code>.</li>\n<li><b>client_secret</b> - the secret for that same OAuth client, on the same Credentials page.</li>\n<li><b>auth_code</b> - a one-time code from Google (see below). You only need this the first time, or if Google ever stops accepting the saved sign-in.</li>\n</ul>\n\n<h3>Getting the auth_code</h3>\n<ol>\n<li>Fill in project_id, client_id and client_secret first and save.</li>\n<li>Open this link in a browser, after replacing <code>PROJECT_ID</code> and <code>CLIENT_ID</code> with your own values:<br>\n<code>https://nestservices.google.com/partnerconnections/PROJECT_ID/auth?redirect_uri=https://www.google.com&amp;access_type=offline&amp;prompt=consent&amp;client_id=CLIENT_ID&amp;response_type=code&amp;scope=https://www.googleapis.com/auth/sdm.service</code></li>\n<li>Sign in with the Google account your thermostat is on, and turn on the permissions for your home and your thermostat.</li>\n<li>If Google says it hasn\'t verified the app, choose <b>Advanced</b>, then <b>Go to (your project name)</b>. This is your own project, and Google says verification isn\'t required for personal use.</li>\n<li>Click <b>Allow</b> on the remaining screens. Your browser lands on a google.com page. Look at the address bar: the part after <code>code=</code> and before the next <code>&amp;</code> is your code. Copy just that part.</li>\n<li>Paste it into <b>auth_code</b> and save. The plugin trades it for a long-lived sign-in and stores it privately on your eisy. You can then clear the auth_code box.</li>\n</ol>\n<p>The code works <b>once</b> and expires quickly, so paste it soon after you get it. If it fails, get a fresh one.</p>\n<p><b>Note:</b> the link above uses <code>https://www.google.com</code> as the redirect address. Your OAuth client in Google Cloud has to allow that redirect address, as in Google\'s own setup guide.</p>\n\n<h3>Good to know</h3>\n<ul>\n<li>The thermostat is read every 5 minutes, and right after any command you send.</li>\n<li>Google only accepts temperature targets in Celsius. The plugin converts for you and shows values in whichever scale your thermostat is set to.</li>\n<li><b>Eco mode:</b> while Eco is on, Google rejects temperature-target changes and the targets are not reported. Turn Eco off first.</li>\n<li>To change the heat target the thermostat must be in Heat mode, the cool target needs Cool mode, and in Heat/Cool mode both are set together.</li>\n<li>A thermostat in your Google Home that isn\'t shared in step 3 above will not show up.</li>\n</ul>]]>')
        # Additional node classes (nest_thermostat, nest_api) -- construct and self.poly.addNode() them from discover()/start() once their real addresses/names are known (run candidate names/addresses through self.poly.getValidName()/getValidAddress() first).
        self.poly.subscribe(self.poly.START, self.__start, address)
        self.poly.subscribe(self.poly.STOP, self.__stop)
        self.poly.subscribe(self.poly.POLL, self.__poll)
        self.poly.subscribe(self.poly.CONFIG, self.__configHandler)
        self.poly.subscribe(self.poly.CONFIGDONE, self.__configDoneHandler)
        self.poly.subscribe(self.poly.CUSTOMPARAMS, self.parameterHandler)
        self.poly.subscribe(self.poly.CUSTOMNS, self.__customNSHandler)
        self.poly.subscribe(self.poly.CUSTOMDATA, self.__customDataHandler)
        self.poly.subscribe(self.poly.ADDNODEDONE, self.__addNodeDoneHandler)
        self.poly.subscribe(self.poly.DELNODEDONE, self.__removeNodeDoneHandler)
        self.poly.subscribe(self.poly.DISCOVER, self.discover)
        self.poly.subscribe(self.poly.BONJOUR, self.__bonjourHandler)
        self.poly.addNode(self, conn_status='ST')

    def __start(self):
        LOGGER.info("%s: start", self.name)
        try:
            if not self.configDoneAlready:
                with self.configDone:
                    if not self.configDone.wait(timeout=10):
                        LOGGER.error("%s: timed out waiting for configDone", self.name)
                        return
            self.start()
        except Exception as ex:
            LOGGER.error("%s: start failed: %s", self.name, ex)

    def __stop(self):
        LOGGER.info("%s: stop", self.name)
        self.stop()

    def __poll(self, polltype):
        if polltype == "shortPoll":
            self.shortPoll()
        elif polltype == "longPoll":
            self.longPoll()

    def __configHandler(self, config):
        self.processConfig(config)

    def __configDoneHandler(self):
        LOGGER.info("%s: config done", self.name)
        with self.configDone:
            self.configDoneAlready = True
            self.configDone.notifyAll()

    def __addNodeDoneHandler(self, data):
        LOGGER.debug("%s: add node done: %s", self.name, data)

    def __removeNodeDoneHandler(self, data):
        LOGGER.debug("%s: remove node done: %s", self.name, data)

    def __customNSHandler(self, key, data):
        self.customParamHandler(key, data)

    def __customDataHandler(self, data):
        LOGGER.debug("%s: custom data: %s", self.name, data)

    def __bonjourHandler(self, response):
        LOGGER.debug("%s: bonjour: %s", self.name, response)

    # --- developer-authored overrides (edit freely; regeneration preserves them) ---

    def start(self):
        import nest_api
        self.nest_started = True
        try:
            nest_api.connect_and_discover(self)
        except Exception:
            LOGGER.exception('Nest startup failed')

    def stop(self, *args, **kwargs):
        pass

    def discover(self, *args, **kwargs):
        import nest_api
        try:
            nest_api.connect_and_discover(self)
        except Exception:
            LOGGER.exception('Nest discovery failed')

    def shortPoll(self, *args, **kwargs):
        import nest_api
        try:
            if getattr(self, 'nest_nodes', None):
                nest_api.refresh_all(self)
        except Exception:
            LOGGER.exception('Nest refresh failed')

    def longPoll(self, *args, **kwargs):
        import nest_api
        try:
            if not getattr(self, 'nest_nodes', None) and getattr(self, 'nest_started', False):
                nest_api.connect_and_discover(self)
        except Exception:
            LOGGER.exception('Nest reconnect failed')

    def processConfig(self, *args, **kwargs):
        pass

    def parameterHandler(self, params):
        import threading
        import nest_api
        self.nest_params = {str(k): str(v).strip() for k, v in (params or {}).items()}
        nest_api.reset_cache(self)
        if getattr(self, 'nest_started', False):
            threading.Thread(target=nest_api.connect_and_discover, args=(self,), daemon=True).start()

    def customParamHandler(self, *args, **kwargs):
        pass

    # --- command dispatch (profile cmds.accepts; see udi_interface.Node.runCmd) ---
    commands = {'DISCOVER': discover}
